int read_value(const int *values, size_t length, size_t index, int *result) {
    if (index >= length || result == NULL) {
        return 0;
    }
    *result = values[index];
    return 1;
}

size_t bounded_length(const char *text, size_t maximum) {
    size_t length = 0;
    while (length < maximum && text[length] != '\0') {
        ++length;
    }
    return length;
}
